#nullable enable // autogenerated

using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using PVZEngine.Entities;
using PVZEngine.Level;

namespace MVZ2.GameContent.Enemies
{
    [EntityBehaviourDefinition(VanillaEntityBehaviourNames.jackDullahan_Move)]
    public class JackDullahan_MoveBehaviour : AIEntityBehaviour
    {
        public JackDullahan_MoveBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            if (entity.State == STATE_WALK || entity.State == STATE_SPECIAL_MOVE)
            {
                entity.UpdateWalkVelocity();
            }
        }
        public const int STATE_WALK = VanillaEnemyStates.WALK;
        public const int STATE_SPECIAL_MOVE = VanillaEnemyStates.SPECIAL_MOVE;
    }
}
